    def test_add_tags(self, svc):
        task = svc.create("t", tags=["alpha"])
        updated = svc.add_tags(task.id, ["beta", "gamma"])
        assert [t.name for t in updated.tags] == ["alpha", "beta", "gamma"]

    def test_add_duplicate_tags_deduplicates(self, svc):
        task = svc.create("t", tags=["alpha"])
        updated = svc.add_tags(task.id, ["alpha", "beta"])
        assert [t.name for t in updated.tags] == ["alpha", "beta"]

    def test_remove_tag(self, svc):
        task = svc.create("t", tags=["alpha", "beta"])
        updated = svc.remove_tag(task.id, "alpha")
        assert [t.name for t in updated.tags] == ["beta"]

    def test_remove_tag_not_present_raises(self, svc):
        task = svc.create("t", tags=["alpha"])
        with pytest.raises(ValueError, match="not attached"):
            svc.remove_tag(task.id, "beta")

    def test_remove_tag_not_found_raises(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.remove_tag(999, "foo")


